mapper.update:
UPDATE wm_refresh_token
SET revoked_at = NOW(),
    replaced_by = #{newJtiHash}
WHERE jti_hash = #{oldJtiHash}
  AND revoked_at IS NULL

UPDATE wm_user_auth SET
  failed_login_count = failed_login_count + 1
WHERE user_auth_seq = #{userAuthSeq}

UPDATE wm_user SET
  last_login_at = NOW()
WHERE user_seq = #{userSeq}

UPDATE wm_otp_verification
SET fail_count = fail_count + 1
WHERE otp_seq = #{otpSeq}
